from lib import *
S = SS('p61')
steps = [
    step("套接字上收到的 HTTP 响应字节原样放进 WARC response 记录(记录头:WARC-Type、WARC-Record-ID、WARC-Date、WARC-Target-URI、两个摘要、Content-Length),用 warcio 1.8.1 读回:plain、gzip、chunked 三种传输方式都读回了正确的类型、URI、状态 200,content_stream 给出的正文 16484 字节,和原 HTML 一致,warcio 的摘要核对都通过。记录大小:plain 16951 字节、gzip 9159 字节、chunked 17001 字节。另外:chunked 记录的 WARC-Payload-Digest 如果改成“去掉分块格式之后的正文”的摘要,warcio 的摘要核对失败(payload digest failed)——它是对头后面的原始字节算的;规范对此怎么规定我没有核对,只能说 warcio 1.8.1 是这样。", t=tl(S(1)), done=lidx(S(1), 'plain    套接字上'), mark=lidx(S(1), '改算'), b=bars([['plain 记录', 16951, '16951'], ['gzip 记录', 9159, '9159'], ['chunked 记录', 17001, '17001']], 17500, done=[0, 1, 2]), kv=KV([['写进去的', '套接字上的字节原样'], ['warcio 读回', '三种都与原 HTML 一致'], ['chunked 摘要算在去分块的正文上', 'warcio 核对失败']], ['写进去的'])),
    step("gzip 压缩的响应,三种写法:(a) 套接字字节原样——记录里的正文 8640 字节,头里 Content-Length=8640、Content-Encoding=gzip,和服务器发出的相同;(b) requests 的 .content(已解压 16434 字节)接在原样的头后面——正文 16434 字节,头里却还写着 Content-Length=8640 和 gzip,与服务器发出的字节不同;(c) 解压后的正文,头里去掉 Content-Encoding、Content-Length 改成 16434——自洽,但仍不是服务器发出的字节。三种 warcio 都读回 16434 字节、与原 HTML 相同——warcio 没有对(b)报错。要拿原始字节:stream=True 后 resp.raw.read(decode_content=False),8640 字节,与套接字相同;chunked 的响应 resp.raw 读出 16434 字节(分块格式已被去掉,套接字上是 16477),而 resp.headers 里仍有 Transfer-Encoding: chunked。", t=tl(S(2)), done=lidx(S(2), '(a) 套接字上的字节原样'), mark=lidx(S(2), '(b) requests'), b=bars([['(a) 记录里的正文', 8640, '8640'], ['(b)(c) 记录里的正文', 16434, '16434'], ['(b) 头里声明的长度', 8640, '8640']], 17000, done=[0], mark=[1, 2]), kv=KV([['(a)', '与服务器发出的字节相同'], ['(b)', '头与正文对不上,warcio 不报错'], ['(c)', '自洽,但不是原始字节']], ['(b)'])),
    step("5000 条响应(每条正文约 16 KB,plain、gzip、chunked 轮流)的存储:未压缩 .warc 68.2 MiB(写 0.03 秒);每条记录单独 gzip 成一个成员 43.4 MiB(0.97 秒);整个文件一个 gzip 流 40.2 MiB(1.36 秒)。整流只小 3.2 MiB(约 7%),但 warcio 读它抛出 ArchiveLoadFailed:“non-chunked gzip file detected, gzip block continues…”——它要求每条记录是一个独立的 gzip 成员。", t=tl(S(3)), done=lidx(S(3), '每条记录单独 gzip(.warc.gz)'), mark=lidx(S(3), '整个文件一个 gzip 流'), b=bars([['不压缩 MiB', 68.2, '68.2'], ['每条单独 gzip MiB', 43.4, '43.4'], ['整个文件一个 gzip 流 MiB', 40.2, '40.2']], 70, done=[1], mark=[2]), kv=KV([['不压缩', '68.2 MiB'], ['每条单独 gzip', '43.4 MiB,warcio 能读'], ['整流 gzip', '40.2 MiB,warcio 报错']], ['每条单独 gzip'])),
    step("随机读一条:有偏移索引(每条的起点和长度),seek 到起点读那么多字节再 gzip 解压,200 次随机读取平均每次 0.044 毫秒,读出的字节和写入的完全一致;没有索引,用 warcio 从头迭代去找第 3000 条,153 毫秒;整个文件一个 gzip 流则要解压整个文件,117 毫秒(没有测解压到某位置就停的情形)。5000 条的文件差距是 3000 倍以上;文件越大差距越大。", t=tl(S(4)), done=lidx(S(4), '每条单独 gzip + 偏移索引'), mark=lidx(S(4), '没有索引'), b=bars([['有索引(毫秒)', 0.044, '0.044'], ['无索引扫描到第 3000 条(毫秒)', 153, '153'], ['整流解压整个文件(毫秒)', 117, '117']], 160, done=[0], mark=[1, 2]), kv=KV([['有偏移索引', '0.044 毫秒'], ['顺序扫描到第 3000 条', '153 毫秒'], ['整流 gzip', '解压整个文件 117 毫秒']], ['有偏移索引'])),
    step("revisit 记录:5000 个 URL 里 1500 个(30%)的正文与前面某个 URL 的字节完全相同,写成只含 HTTP 头、带 WARC-Refers-To 和 payload 摘要的 revisit 记录:每条单独 gzip 的文件从 43.4 MiB 降到 30.9 MiB,省 29%。revisit 只保留头,正文要到被引用的那条记录里去找,所以引用的记录必须保留。", t=tl(S(5)), done=lidx(S(5), '5000 个 URL 里有 1500 个'), b=bars([['完整写 MiB', 43.4, '43.4'], ['用 revisit MiB', 30.9, '30.9']], 45, done=[1], mark=[0]), kv=KV([['重复的 URL', '1500 / 5000'], ['完整写', '43.4 MiB'], ['revisit', '30.9 MiB,省 29%']], ['revisit'])),
    step("写到第 3000 条中间被杀(截断):每条单独 gzip 的文件,warcio 顺序读到 3001 条,没有报错,摘要核对结果 3000 条通过、1 条为 None(没有核对),最后一条头里声明 Content-Length=16366。用 zlib 逐个成员地走:完整成员 3000 个,最后一个完整成员结束在偏移 27324868,文件多出 4526 字节(走一遍 0.85 秒),把文件截到那里就能继续追加。有偏移索引时:第 3000 条结束偏移 27333920 大于文件大小 27329394,可判定它不完整。整流 gzip 同样比例截断,zlib 流式解压得到 40.9 MiB,自己解析 Content-Length 数出完整记录 2999 条。", t=tl(S(6)), done=lidx(S(6), '用 zlib 逐个 gzip 成员地走'), mark=lidx(S(6), '每条单独 gzip,截断在'), b=bars([['warcio 顺序读到', 3001, '3001'], ['摘要核对通过', 3000, '3000'], ['完整的 gzip 成员', 3000, '3000']], 3100, done=[1, 2], mark=[0]), kv=KV([['被截断的最后一条', 'warcio 不报错,摘要核对为 None'], ['恢复', '走到最后一个完整成员再截断'], ['有偏移索引', '结束偏移 > 文件大小 → 不完整']], ['被截断的最后一条'])),
]
A = mkartp('p61', 61, '爬虫,WARC,原始响应,归档,gzip,revisit,warcio,Python,真实验证,动画演示',
    '在本机用手写的 WARC 记录实测:套接字字节原样写入并用 warcio 读回、chunked 的摘要要算在存下的字节上、requests 解码后再存会让头与正文对不上、每条记录单独 gzip 才能被 warcio 读并按偏移随机访问、revisit 记录省 29%、写到一半被截断后怎么恢复。',
    '爬虫存下的“原始响应”如果只留解析后的字段,规则改了就没法重新解析。把原始响应按 WARC 格式存起来,可以随时重放。这篇自己手写 WARC 记录,用 warcio 读回核对,逐项测写法上的坑。',
    [('8640 对 16434', 'gzip 响应在记录里存的正文字节(原样) 与 requests 的 .content 解压后的字节;后者接在原样的头(Content-Length=8640)后面就对不上了'), ('0.044 对 153 毫秒', '有偏移索引的随机读取 与 没有索引顺序扫描到第 3000 条(5000 条的文件)'), ('43.4 对 30.9 MiB', '30% 的重复正文,完整写入 与 写成 revisit 记录 的文件大小')],
    [('原样写一条', '<p>WARC 记录由一组记录头(类型、记录 ID、时间、URL、摘要、Content-Length)加一段内容块组成;response 记录的内容块就是 HTTP 响应的完整字节(状态行、头、正文)。我从套接字读到响应字节后原样放入,用 warcio 1.8.1 读回:类型、URI、状态码、正文都对,摘要核对通过,plain、gzip、chunked 三种传输方式都一样。chunked 的响应,把 WARC-Payload-Digest 算成“去掉分块格式之后的正文”,warcio 的摘要核对会失败;它是对头后面存下来的字节原样算的。规范对此怎么规定我没有核对,这里只说 warcio 1.8.1 的行为:摘要要算在你实际存下的字节上。</p>'),
     ('别存解码之后的字节', '<p>requests 的 .content 是解压后的,resp.raw 虽然没有分块格式了,但 resp.headers 里还有 Transfer-Encoding: chunked。把解码后的正文接在原来的头后面,头(Content-Length=8640、Content-Encoding: gzip)和正文(16434 字节)就对不上,而 warcio 读回时并没有报错——不报错不等于没问题。要原样保存,就在套接字层抓字节,或者 stream=True 后用 resp.raw.read(decode_content=False) 并自己处理分块;(c) 去掉头里的编码信息再存解压后的正文是自洽的,但存下的已不是服务器发出的字节。</p>'),
     ('每条记录单独压缩', '<p>每条记录压成一个独立的 gzip 成员再拼接,得到 43.4 MiB;整个文件一个 gzip 流是 40.2 MiB,只小了约 7%,但 warcio 读它直接抛出 ArchiveLoadFailed,要求每条记录一个成员。</p>'),
     ('偏移索引', '<p>每条记录单独压缩的好处是可以记下它的偏移和长度,以后 seek 过去只解压这一条:200 次随机读取平均 0.044 毫秒;没有索引要从头扫,找第 3000 条用了 153 毫秒。写入时把偏移记进索引(CDX 之类)是这种格式的用法。</p>'),
     ('重复内容', '<p>正文与已有记录字节完全相同时,可以只存 HTTP 头,用 revisit 记录引用第一次(WARC-Refers-To、payload 摘要):实验里 30% 重复,文件小 29%。被引用的记录不能删。</p>'),
     ('写到一半被杀', '<p>进程被杀后,每条单独 gzip 的文件可以逐个成员地走到最后一个完整成员,截断后继续追加。但 warcio 顺序读被截断的文件时,最后那条残缺的记录不报错、摘要核对结果是 None(没有核对),所以读取侧不能只看“没报错”,要看摘要核对结果或比对声明的 Content-Length 与实际读到的长度。有偏移索引时,结束偏移大于文件大小就说明那条没写完。</p>')],
    steps,
    [ENV_P + '。服务器是本机的 Srv(每个请求返回由页面编号确定的约 16 KB HTML,plain / gzip / chunked 三种传输方式),用裸套接字抓取响应字节;WARC 记录是我手写的(WARC/1.1 头、Content-Length、sha1 base32 摘要),用临时安装的 warcio 1.8.1 读回核对(用完删除);5000 条记录的文件在临时目录里,用完删除;各情形跑一次,时间是单次测量(写入时间包含 gzip 压缩)',
     '没有验证:WARC 规范原文(只验证了 warcio 1.8.1 的行为,比如 chunked 的摘要是怎么算的);request 记录、metadata 记录、warcinfo 记录;大文件(GB 级)和并发写入;WARC-Truncated(正文太大被截断时的标记);zstd 压缩的 WARC;其它读取工具(如 Wayback 的 pywb)对这些记录的处理;真实站点上带 Cookie、重定向链的响应怎么存'],
    'WARC 归档')
